"""Template for the executable offline ZIP; generated by build_offline.py."""

import argparse
import hashlib
import importlib.util
from pathlib import Path
import re
import stat
import sys
import tempfile
import zipfile

COMMIT = "__APPLICATION_COMMIT__"
PAYLOADS = {}
EXPECTED = {"install_host.py", "SHA256SUMS", "host-files.tar.gz", "little-garden-linux-amd64.tar.gz"}


def unpack_verified(archive, target):
    if set(PAYLOADS) != EXPECTED or not re.fullmatch(r"[a-f0-9]{40}", COMMIT):
        raise RuntimeError("离线包的版本或文件清单无效。")
    with zipfile.ZipFile(archive) as bundle:
        entries = bundle.infolist()
        if len(entries) != len(EXPECTED) + 1 or {entry.filename for entry in entries} != EXPECTED | {"__main__.py"}:
            raise RuntimeError("离线包包含未知或重复文件。")
        contents = {}
        for entry in entries:
            if entry.is_dir() or stat.S_IFMT(entry.external_attr >> 16) not in (0, stat.S_IFREG):
                raise RuntimeError("离线包包含非普通文件。")
            if entry.filename == "__main__.py":
                continue
            expected = PAYLOADS[entry.filename]
            if entry.file_size != expected["size"] or entry.file_size > 256 * 1024 * 1024:
                raise RuntimeError("离线包文件大小不匹配。")
            content = bundle.read(entry)
            if hashlib.sha256(content).hexdigest() != expected["sha256"]:
                raise RuntimeError(f"离线包校验失败：{entry.filename}。")
            contents[entry.filename] = content
        # All names and bytes are checked before writing or importing any payload.
        for name, content in contents.items():
            (target / name).write_bytes(content)


def main():
    parser = argparse.ArgumentParser(description="Little Garden 离线安装包（Linux amd64）")
    parser.add_argument("--domain")
    parser.add_argument("--directory", default="/srv/little-garden")
    parser.add_argument("--prepare-only", action="store_true")
    parser.add_argument("--verify-only", action="store_true")
    args = parser.parse_args()
    if not args.verify_only and not args.domain:
        parser.error("安装时必须提供 --domain")
    with tempfile.TemporaryDirectory(prefix="little-garden-offline-") as temporary:
        root = Path(temporary)
        unpack_verified(sys.argv[0], root)
        print(f"离线包校验通过，应用版本：{COMMIT[:12]}", flush=True)
        if args.verify_only:
            return
        spec = importlib.util.spec_from_file_location("garden_installer", root / "install_host.py")
        installer = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(installer)
        arguments = ["--domain", args.domain, "--commit", COMMIT, "--directory", args.directory,
                     "--package-directory", str(root)]
        if args.prepare_only:
            arguments.append("--prepare-only")
        installer.main(arguments)


if __name__ == "__main__":
    try:
        main()
    except (Exception, KeyboardInterrupt) as error:
        print(f"安装停止：{error}", file=sys.stderr)
        sys.exit(1)
